/**
 * Extract the root portion of an absolute path.
 * Handles DOS/NetWare drive letters and UNC paths.
 * @param path the normalized absolute path
 * @param sep the file separator character
 * @return the root portion of the path
 */
private String extractRoot(String path, char sep) {
    int colon = path.indexOf(':');
    if (colon > 0 && (ON_DOS || ON_NETWARE)) {
        String root = path.substring(0, colon + 1) + sep;
        int nextIndex = (path.length() > colon + 1 && path.charAt(colon + 1) == sep) ? colon + 2 : colon + 1;
        // Eliminate consecutive slashes after the drive spec
        StringBuilder sb = new StringBuilder();
        for (int i = nextIndex; i < path.length(); i++) {
            if (path.charAt(i) != sep || i == 0 || path.charAt(i - 1) != sep) {
                sb.append(path.charAt(i));
            }
        }
        path = sb.toString();
    } else if (path.length() > 1 && path.charAt(1) == sep) {
        // UNC drive
        int nextsep = path.indexOf(sep, 2);
        nextsep = path.indexOf(sep, nextsep + 1);
        root = (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
    } else {
        root = File.separator;
    }
    return root;
}

