}

private void listSourceFiles() {
    for (int i = 0; i < compileList.length; i++) {
        log(compileList[i].getAbsolutePath());
    }
}

private CompilerAdapter resolveCompilerAdapter() {
    String compilerImpl = getCompiler();
    return nestedAdapter != null ? nestedAdapter :
        CompilerAdapterFactory.getCompiler(compilerImpl, this,
                                           createCompilerClasspath());
}

private void handleCompilationSuccess() {
    if (createMissingPackageInfoClass) {
        try {
            generateMissingPackageInfoClasses(getDestinationDirectory());
        } catch (IOException x) {
            throw new BuildException(x, getLocation());
        }
    }
}

private void handleCompilationFailure() {
    this.taskSuccess = false;
    if (errorProperty != null) {
        getProject().setNewProperty(errorProperty, "true");
    }
    if (failOnError) {
        throw new BuildException(FAIL_MSG, getLocation());
    } else {
        log(FAIL_MSG, Project.MSG_ERR);
    }
}

private File getDestinationDirectory() {
    return destDir != null ? destDir
        : getProject().resolveFile(src.list()[0]);
}

protected void compile() {
    if (compileList.length == 0) {
        return;
    }

    logCompilationStart();
    logSourceFilesIfRequested();
    CompilerAdapter adapter = createCompilerAdapter();
    boolean success = executeCompiler(adapter);
    handleCompilationResult(success);
}

private void logCompilationStart() {
    log("Compiling " + compileList.length + " source file"
        + (compileList.length == 1 ? "" : "s")
        + (destDir != null ? " to " + destDir : ""));
}

private void logSourceFilesIfRequested() {
    if (!listFiles) {
        return;
    }
    for (File file : compileList) {
        log(file.getAbsolutePath());
    }
}

private CompilerAdapter createCompilerAdapter() {
    String compilerImpl = getCompiler();
    CompilerAdapter adapter =
        nestedAdapter != null ? nestedAdapter :
        CompilerAdapterFactory.getCompiler(compilerImpl, this,
                                           createCompilerClasspath());
    adapter.setJavac(this);
    return adapter;
}

private boolean executeCompiler(CompilerAdapter adapter) {
    return adapter.execute();
}

private void handleCompilationResult(boolean success) {
    if (success) {
        handleSuccessfulCompilation();
    } else {
        handleFailedCompilation();
    }
}

private void handleSuccessfulCompilation() {
    if (createMissingPackageInfoClass) {
        try {
            File baseDir = destDir != null ? destDir
                : getProject().resolveFile(src.list()[0]);
            generateMissingPackageInfoClasses(baseDir);
        } catch (IOException e) {
            throw new BuildException(e, getLocation());
        }
    }
}

private void handleFailedCompilation() {
    taskSuccess = false;
    if (errorProperty != null) {
        getProject().setNewProperty(errorProperty, "true");
    }
    if (failOnError) {
        throw new BuildException(FAIL_MSG, getLocation());
    } else {
        log(FAIL_MSG, Project.MSG_ERR);
    }
}

private String assumedJavaVersion() {
    if (JavaEnvUtils.isJavaVersion(JavaEnvUtils.JAVA_1_4)) {
        return JAVAC14;
    } else if (JavaEnvUtils.isJavaVersion(JavaEnvUtils.JAVA_1_5)) {
        return JAVAC15;
    } else if (JavaEnvUtils.isJavaVersion(JavaEnvUtils.JAVA_1_6)) {
        return JAVAC16;
    } else if (JavaEnvUtils.isJavaVersion(JavaEnvUtils.JAVA_1_7)) {
        return JAVAC17;
    } else if (JavaEnvUtils.isJavaVersion(JavaEnvUtils.JAVA_1_8)) {
        return JAVAC18;
    } else {
        return CLASSIC;
    }
}

private boolean isJdkCompiler(String compilerImpl) {
    return MODERN.equals(compilerImpl)
        || CLASSIC.equals(compilerImpl)
        || JAVAC18.equals(compilerImpl)
        || JAVAC17.equals(compilerImpl)
        || JAVAC16.equals(compilerImpl)
        || JAVAC15.equals(compilerImpl)
        || JAVAC14.equals(compilerImpl)
        || JAVAC13.equals(compilerImpl)
        || JAVAC12.equals(compilerImpl)
        || JAVAC11.equals(compilerImpl);
}

private String getAltCompilerName(String anImplementation) {
    if (isModernVariant(anImplementation)) {
        return MODERN;
    }
    if (isClassicVariant(anImplementation)) {
        return CLASSIC;
    }
    if (MODERN.equalsIgnoreCase(anImplementation)) {
        String nextSelected = assumedJavaVersion();
        if (isModernVariant(nextSelected)) {
            return nextSelected;
        }
    }
    if (CLASSIC.equalsIgnoreCase(anImplementation)) {
        return assumedJavaVersion();
    }
    if (EXTJAVAC.equalsIgnoreCase(anImplementation)) {
        return assumedJavaVersion();
    }
    return null;
}

private boolean isModernVariant(String impl) {
    return JAVAC17.equalsIgnoreCase(impl)
        || JAVAC18.equalsIgnoreCase(impl)
        || JAVAC16.equalsIgnoreCase(impl)
        || JAVAC15.equalsIgnoreCase(impl)
        || JAVAC14.equalsIgnoreCase(impl)
        || JAVAC13.equalsIgnoreCase(impl);
}

private boolean isClassicVariant(String impl) {
    return JAVAC12.equalsIgnoreCase(impl)
        || JAVAC11.equalsIgnoreCase(impl);
}

