    private static void siftUp(int[] heap, int[] weight, int idx) {
        int tmp = heap[idx];
        while (idx > 1 && weight[tmp] < weight[heap[idx >> 1]]) {
            heap[idx] = heap[idx >> 1];
            idx >>= 1;
        }
        heap[idx] = tmp;
