            weight[nNodes] = ((weight[n1] & 0xffffff00) + (weight[n2] & 0xffffff00))
                | (1 + Math.max(weight[n1] & 0x000000ff, weight[n2] & 0x000000ff));
            parent[nNodes] = -1;
