    public Object findOperationByName(Object trans, String opname) {
        if (!(trans instanceof Transition)) {
            throw new IllegalArgumentException();
        }
        try {
            Object stateMachine = getStateMachine(trans);
            if (stateMachine == null) {
                return null;
            }
            Object context = Model.getFacade().getContext(stateMachine);
            Classifier classifier = findClassifier(context);
            if (classifier != null) {
                Feature found = findOperationInClassifier(classifier, opname);
                if (found != null) {
                    return found;
                }
            }
            Namespace pack = findNamespaceForSearch(context, classifier);
            if (pack != null) {
                Feature found = findOperationInPackagedElements(pack, opname);
                if (found != null) {
                    return found;
                }
            }
        } catch (InvalidObjectException e) {
            throw new InvalidElementException(e);
        }
        return null;
    }

    private Classifier findClassifier(Object context) {
        if (context instanceof Classifier) {
            return (Classifier) context;
        }
        if (context instanceof BehavioralFeature) {
            return ((BehavioralFeature) context).getOwner();
        }
        return null;
    }

    private Feature findOperationInClassifier(Classifier classifier, String opname) {
        List<Feature> features = classifier.getFeature();
        for (Feature f : features) {
            if (f instanceof Operation && opname.equals(f.getName())) {
                return f;
            }
        }
        return null;
    }

    private Namespace findNamespaceForSearch(Object context, Classifier classifier) {
        if (context instanceof UmlPackage) {
            return (Namespace) context;
        }
        if (classifier == null) {
            return null;
        }
        Namespace parent = classifier.getNamespace();
        while (parent instanceof Classifier) {
            if (parent.getNamespace() == null) {
