_link_attrs = set(html.defs.link_attrs) | {XLINK('href'), 'poster'}


def iterlinks(root, find_links_in_css=True):
    '''
    Iterate over all links in a OEB Document.

    :param root: A valid lxml.etree element.
    '''
    assert etree.iselement(root)

    for el in root.iter():
        attribs = el.attrib
        try:
            tag = barename(el.tag).lower()
        except Exception:
            continue

        if tag == 'object':
            for link_tuple in _process_object_tag(el, attribs):
                yield link_tuple
        else:
            for link_tuple in _process_regular_tag(el, attribs):
                yield link_tuple

        if not find_links_in_css:
            continue
        for link_tuple in _process_css_links(el, tag):
            yield link_tuple


def _process_object_tag(el, attribs):
    codebase = None
    if 'codebase' in attribs:
        codebase = el.get('codebase')
        yield (el, 'codebase', codebase, 0)
    for attrib in ('classid', 'data'):
        if attrib in attribs:
            value = el.get(attrib)
            if codebase is not None:
                value = urljoin(codebase, value)
            yield (el, attrib, value, 0)
    if 'archive' in attribs:
        for match in _archive_re.finditer(el.get('archive')):
            value = match.group(0)
            if codebase is not None:
                value = urljoin(codebase, value)
            yield (el, 'archive', value, match.start())


def _process_regular_tag(el, attribs):
    for attr in attribs:
        if attr in _link_attrs:
            yield (el, attr, attribs[attr], 0)


def _process_css_links(el, tag):
    if tag == 'style' and el.text:
        for match in _css_url_re.finditer(el.text):
            yield (el, None, match.group(1), match.start(1))
        for match in _css_import_re.finditer(el.text):
            yield (el, None, match.group(1), match.start(1))
    if 'style' in el.attrib:
        for match in _css_url_re.finditer(el.attrib['style']):
            yield (el, 'style', match.group(1), match.start(1))

