    '''
    Iterate over all links in an OEB Document.

    Yields tuples of (element, attribute_name, value, position).
    '''
    assert etree.iselement(root)

    for el in root.iter():
        attrs = el.attrib
        try:
            tag = barename(el.tag).lower()
        except Exception:
            continue

        if tag == 'object':
            _handle_object_element(el, attrs, _link_attrs)
        else:
            for attr in attrs:
                if attr in _link_attrs:
                    yield (el, attr, attrs[attr], 0)

        if not find_links_in_css:
            continue

        if tag == 'style' and el.text:
            for match in _css_url_re.finditer(el.text):
                yield (el, None, match.group(1), match.start(1))
            for match in _css_import_re.finditer(el.text):
                yield (el, None, match.group(1), match.start(1))

        if 'style' in attrs:
            for match in _css_url_re.finditer(attrs['style']):
                yield (el, 'style', match.group(1), match.start(1))


def _handle_object_element(el, attrs, link_attrs):
    """
    Handle <object> tag link extraction with codebase-relative paths.
    Yields (element, attribute, value, position) tuples.
    """
    codebase = attrs.get('codebase')
    if codebase is not None:
        yield (el, 'codebase', codebase, 0)

    for attr in ('classid', 'data'):
        if attr in attrs:
            value = attrs[attr]
            if codebase is not None:
                value = urljoin(codebase, value)
            yield (el, attr, value, 0)

    if 'archive' in attrs:
        archive_val = attrs['archive']
        for match in _archive_re.finditer(archive_val):
            value = match.group(0)
            if codebase is not None:
                value = urljoin(codebase, value)
            yield (el, 'archive', value, match.start())

