def properties_for_id_with_scheme(item_id, prefixes, refines):
    """
    Extract metadata properties for a given item ID, including scheme information.
    Returns a dict: {property_name: (scheme_namespace, scheme_value, text_value)}
    """
    ans = {}
    if not item_id:
        return ans

    for elem in refines[item_id]:
        key = elem.get('property')
        if not key:
            continue

        val = (elem.text or '').strip()
        if not val:
            continue

        scheme_ns, scheme = _extract_scheme(elem, prefixes)
        ans[key] = (scheme_ns, scheme, val)

    return ans


def _extract_scheme(elem, prefixes):
    """
    Extract and resolve scheme information from an element.
    Returns (scheme_namespace, scheme_value) or (None, None) if no valid scheme.
    """
    raw_scheme = elem.get('scheme')
    if not raw_scheme:
        return None, None

    raw_scheme = raw_scheme.strip()
    if not raw_scheme:
        return None, None

    # Split into prefix and local part
    parts = raw_scheme.partition(':')
    prefix, sep, local = parts
    if not sep or not prefix or not local:
        return None, None

    # Look up namespace for prefix
    namespace = prefixes.get(prefix)
    if not namespace:
        return None, None

    return namespace, local

