def _extract_scheme_namespace(elem, prefixes):
    """Extract scheme namespace and value from an element."""
    scheme = elem.get('scheme') or None
    if scheme is None:
        return None, None

    p, _, r = scheme.partition(':')
    if not p or not r:
        return None, None

    ns = prefixes.get(p)
    if not ns:
        return None, scheme

    return ns, r

