def media_property(cls):
    def _media(self):
        # Get the media property of the superclass, if it exists
        sup_cls = super(cls, self)
        try:
            base = sup_cls.media
        except AttributeError:
            base = Media()

        # Get the media definition for this class
        definition = getattr(cls, 'Media', None)
        if definition:
            extend = getattr(definition, 'extend', True)
            if extend:
                return _build_media_with_extension(base, definition, extend)
            else:
                return Media(definition)
        else:
            return base
    return property(_media)


def _build_media_with_extension(base, definition, extend):
    """
    Build media by extending base media with the given definition.
    Handles both default (True) and explicit extend lists.
    """
    if extend is True:
        m = base
    else:
        m = Media()
        for medium in extend:
            m = m + base[medium]
    return m + Media(definition)

def _extract_select_date_widget_dates(data, name, widget):
    """Extract year, month, and day values for SelectDateWidget."""
    y = data.get(widget.year_field % name)
    m = data.get(widget.month_field % name)
    d = data.get(widget.day_field % name)
    return y, m, d


def _handle_zero_date_selection(y, m, d):
    """Return None if all date components are '0'."""
    if y == m == d == "0":
        return None
    return False


def _format_localized_date(y, m, d, input_format):
    """Format a date using local input format, handling validation."""
    try:
        date_value = datetime.date(int(y), int(m), int(d))
        date_value = datetime_safe.new_date(date_value)
        return date_value.strftime(input_format)
    except ValueError:
        return '%s-%s-%s' % (y, m, d)


def _format Gregorian_date(y, m, d):
    """Format a date as ISO-like string."""
    return '%s-%s-%s' % (y, m, d)


def _is_date_field_present(data, name, interval):
    """Check if a specific date field is present in data."""
    return '{}_{}'.format(name, interval) in data


