   * @param entity the entity to check
   * @param filter the filter to apply
   * @return true if the entity passes the filter, false otherwise
   */
  private static boolean doesEntityPassFilter(TimelineEntity entity, NameValuePair filter) {
    Object v = entity.getOtherInfo().get(filter.getName());
    if (v == null) {
      Set<Object> vs = entity.getPrimaryFilters().get(filter.getName());
      return vs != null && vs.contains(filter.getValue());
    }
    return v.equals(filter.getValue());
  }

