DatanodeDescriptor getDatanodeDescriptor(String address) {
    DatanodeID dnId = parseDNFromHostsEntry(address);
    String host = dnId.getIpAddr();
    int xferPort = dnId.getXferPort();
    DatanodeDescriptor node = getDatanodeByXferAddr(host, xferPort);
    if (node == null) {
      node = getDatanodeByHost(host);
    }
    if (node == null) {
      String networkLocation = 
          resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

      // If the current cluster doesn't contain the node, fallback to
      // something machine local and then rack local.
      List<Node> rackNodes = getNetworkTopology()
                                   .getDatanodesInRack(networkLocation);
      if (rackNodes != null) {
        // Try something machine local.
        for (Node rackNode : rackNodes) {
          if (((DatanodeDescriptor) rackNode).getIpAddr().equals(host)) {
            node = (DatanodeDescriptor) rackNode;
            break;
          }
        }

        // Try something rack local.
        if (node == null && !rackNodes.isEmpty()) {
          node = (DatanodeDescriptor) (rackNodes
              .get(DFSUtil.getRandom().nextInt(rackNodes.size())));
        }
      }

      // If we can't even choose rack local, just choose any node in the
      // cluster.
      if (node == null) {
        node = (DatanodeDescriptor)getNetworkTopology()
                                   .chooseRandom(NodeBase.ROOT);
      }
    }
    return node;
  }

DatanodeDescriptor getDatanodeDescriptor(String address) {
    DatanodeID dnId = parseDNFromHostsEntry(address);
    String host = dnId.getIpAddr();
    int xferPort = dnId.getXferPort();

    DatanodeDescriptor node = getDatanodeByXferAddr(host, xferPort);
    if (node != null) {
      return node;
    }

    node = getDatanodeByHost(host);
    if (node != null) {
      return node;
    }

    return findFallbackDatanode(dnId);
  }

  /**
   * Find a datanode using fallback logic when exact match is not found.
   * Tries machine-local, then rack-local, then any cluster node.
   *
   * @param dnId the parsed datanode ID from the address string
   * @return best available DatanodeDescriptor per fallback logic
   */
  private DatanodeDescriptor findFallbackDatanode(DatanodeID dnId) {
    String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);
    List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);

    // Try machine-local
    if (rackNodes != null) {
      for (Node rackNode : rackNodes) {
        if (((DatanodeDescriptor) rackNode).getIpAddr().equals(dnId.getIpAddr())) {
          return (DatanodeDescriptor) rackNode;
        }
      }

      // Try rack-local
      if (!rackNodes.isEmpty()) {
        return (DatanodeDescriptor) rackNodes.get(DFSUtil.getRandom().nextInt(rackNodes.size()));
      }
    }

    // Fallback to any node in the cluster
    return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
  }

DatanodeDescriptor getDatanodeDescriptor(String address) {
  DatanodeID dnId = parseDNFromHostsEntry(address);
  String host = dnId.getIpAddr();
  int xferPort = dnId.getXferPort();

  DatanodeDescriptor node = getDatanodeByXferAddr(host, xferPort);
  if (node == null) {
    node = getDatanodeByHost(host);
  }
  if (node == null) {
    node = findBestNodeFallback(host, dnId);
  }
  return node;
}

/**
 * Attempts to find a suitable datanode by falling back to machine-local,
 * rack-local, or any random node in the cluster.
 *
 * @param host IP address of the target datanode
 * @param dnId original DatanodeID for resolving network location
 * @return a DatanodeDescriptor matching best effort criteria, or null if none found
 */
private DatanodeDescriptor findBestNodeFallback(String host, DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);
  List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);

  if (rackNodes != null) {
    DatanodeDescriptor node = findMachineLocalNode(rackNodes, host);
    if (node == null && !rackNodes.isEmpty()) {
      node = findRandomRackLocalNode(rackNodes);
    }
    return node;
  }

  // Fallback to any node in the cluster
  return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
}

/**
 * Searches for a machine-local node in the given list of rack nodes.
 *
 * @param rackNodes list of candidate nodes in the same rack
 * @param host IP address to match
 * @return matching DatanodeDescriptor or null if none found
 */
private DatanodeDescriptor findMachineLocalNode(List<Node> rackNodes, String host) {
  for (Node rackNode : rackNodes) {
    if (((DatanodeDescriptor) rackNode).getIpAddr().equals(host)) {
      return (DatanodeDescriptor) rackNode;
    }
  }
  return null;
}

/**
 * Selects a random node from the given rack-local node list.
 *
 * @param rackNodes non-empty list of rack-local candidate nodes
 * @return random DatanodeDescriptor selected from the list
 */
private DatanodeDescriptor findRandomRackLocalNode(List<Node> rackNodes) {
  return (DatanodeDescriptor) rackNodes.get(DFSUtil.getRandom().nextInt(rackNodes.size()));
}

DatanodeDescriptor getDatanodeDescriptor(String address) {
    DatanodeID dnId = parseDNFromHostsEntry(address);
    String host = dnId.getIpAddr();
    int xferPort = dnId.getXferPort();
    DatanodeDescriptor node = getDatanodeByXferAddr(host, xferPort);
    if (node == null) {
      node = getDatanodeByHost(host);
    }
    if (node == null) {
      String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);
      DatanodeLookupContext context = DatanodeLookupContext.builder()
          .networkLocation(networkLocation)
          .networkTopology(getNetworkTopology())
          .host(host)
          .random(DFSUtil.getRandom())
          .build();
      node = findDatanodeByLookupContext(context);
    }
    return node;
  }

  /**
   * Find a datanode using pre-resolved context to reduce complexity.
   */
  private DatanodeDescriptor findDatanodeByLookupContext(DatanodeLookupContext context) {
    // Try something machine local.
    for (Node rackNode : context.getRackNodes()) {
      if (((DatanodeDescriptor) rackNode).getIpAddr().equals(context.getHost())) {
        return (DatanodeDescriptor) rackNode;
      }
    }

    // Try something rack local.
    if (!context.getRackNodes().isEmpty()) {
      return (DatanodeDescriptor) context.getRackNodes()
          .get(context.getRandom().nextInt(context.getRackNodes().size()));
    }

    // If we can't even choose rack local, just choose any node in the cluster.
    return (DatanodeDescriptor) context.getNetworkTopology()
        .chooseRandom(NodeBase.ROOT);
  }

  /**
   * Context object for datanode lookup to reduce parameter count and complexity.
   */
  private static class DatanodeLookupContext {
    private final String networkLocation;
    private final NetworkTopology networkTopology;
    private final String host;
    private final Random random;
    private volatile List<Node> rackNodesCache;

    private DatanodeLookupContext(String networkLocation,
        NetworkTopology networkTopology, String host, Random random) {
      this.networkLocation = networkLocation;
      this.networkTopology = networkTopology;
      this.host = host;
      this.random = random;
    }

    private static Builder builder() {
      return new Builder();
    }

    private List<Node> getRackNodes() {
      if (rackNodesCache == null) {
        rackNodesCache = networkTopology.getDatanodesInRack(networkLocation);
      }
      return rackNodesCache;
    }

    private NetworkTopology getNetworkTopology() {
      return networkTopology;
    }

    private String getHost() {
      return host;
    }

    private Random getRandom() {
      return random;
    }

    static class Builder {
      private String networkLocation;
      private NetworkTopology networkTopology;
      private String host;
      private Random random;

      Builder networkLocation(String val) {
        this.networkLocation = val;
        return this;
      }

      Builder networkTopology(NetworkTopology val) {
        this.networkTopology = val;
        return this;
      }

      Builder host(String val) {
        this.host = val;
        return this;
      }

      Builder random(Random val) {
        this.random = val;
        return this;
      }

      DatanodeLookupContext build() {
        Preconditions.checkNotNull(networkLocation, "networkLocation");
        Preconditions.checkNotNull(networkTopology, "networkTopology");
        Preconditions.checkNotNull(host, "host");
        Preconditions.checkNotNull(random, "random");
        return new DatanodeLookupContext(networkLocation, networkTopology, host, random);
      }
    }
  }

DatanodeDescriptor getDatanodeDescriptor(String address) {
    DatanodeID dnId = parseDNFromHostsEntry(address);
    String host = dnId.getIpAddr();
    int xferPort = dnId.getXferPort();
    DatanodeDescriptor node = getDatanodeByXferAddr(host, xferPort);
    if (node == null) {
      node = getDatanodeByHost(host);
    }
    if (node == null) {
      String networkLocation = 
          resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

      // If the current cluster doesn't contain the node, fallback to
      // something machine local and then rack local.
      List<Node> rackNodes = getNetworkTopology()
                                   .getDatanodesInRack(networkLocation);
      if (rackNodes != null) {
        // Try something machine local.
        for (Node rackNode : rackNodes) {
          if (((DatanodeDescriptor) rackNode).getIpAddr().equals(host)) {
            node = (DatanodeDescriptor) rackNode;
            break;
          }
        }

        // Try something rack local.
        if (node == null && !rackNodes.isEmpty()) {
          node = (DatanodeDescriptor) (rackNodes
              .get(DFSUtil.getRandom().nextInt(rackNodes.size())));
        }
      }

      // If we can't even choose rack local, just choose any node in the
      // cluster.
      if (node == null) {
        node = (DatanodeDescriptor)getNetworkTopology()
                                   .chooseRandom(NodeBase.ROOT);
      }
    }
    return node;
  }

static Map<String, Object> jsonParse(final HttpURLConnection c, final boolean useErrorStream
      ) throws IOException {
    if (c.getContentLength() == 0) {
      return null;
    }
    final InputStream in = useErrorStream? c.getErrorStream(): c.getInputStream();
    if (in == null) {
      throw new IOException("The " + (useErrorStream? "error": "input") + " stream is null.");
    }
    try {
      final String contentType = c.getContentType();
      if (contentType != null) {
        final MediaType parsed = MediaType.valueOf(contentType);
        if (!MediaType.APPLICATION_JSON_TYPE.isCompatible(parsed)) {
          throw new IOException("Content-Type \"" + contentType
              + "\" is incompatible with \"" + MediaType.APPLICATION_JSON
              + "\" (parsed=\"" + parsed + "\")");
        }
      }
      ObjectMapper mapper = new ObjectMapper();
      return mapper.reader(Map.class).readValue(in);
    } finally {
      in.close();
    }
  }

