  BlockReceiver(final ExtendedBlock block, final StorageType storageType,
      final DataInputStream in,
      final String inAddr, final String myAddr,
      final BlockConstructionStage stage, 
      final long newGs, final long minBytesRcvd, final long maxBytesRcvd, 
      final String clientname, final DatanodeInfo srcDataNode,
      final DataNode datanode, DataChecksum requestedChecksum,
      CachingStrategy cachingStrategy,
      final boolean allowLazyPersist,
      final boolean pinning) throws IOException {
    try {
      this.block = block;
      this.in = in;
      this.inAddr = inAddr;
      this.myAddr = myAddr;
      this.srcDataNode = srcDataNode;
      this.datanode = datanode;
      this.clientname = clientname;
      this.isDatanode = clientname.length() == 0;
      this.isClient = !this.isDatanode;
      this.restartBudget = datanode.getDnConf().restartReplicaExpiry;
      this.datanodeSlowLogThresholdMs = datanode.getDnConf().datanodeSlowIoWarningThresholdMs;
      this.responseInterval = (long) (datanode.getDnConf().socketTimeout * 0.5);
      this.stage = stage;
      this.isTransfer = stage == BlockConstructionStage.TRANSFER_RBW
          || stage == BlockConstructionStage.TRANSFER_FINALIZED;
      this.pinning = pinning;

      if (LOG.isDebugEnabled()) {
        LOG.debug(getClass().getSimpleName() + ": " + block
            + "\n  isClient  =" + isClient + ", clientname=" + clientname
            + "\n  isDatanode=" + isDatanode + ", srcDataNode=" + srcDataNode
            + "\n  inAddr=" + inAddr + ", myAddr=" + myAddr
            + "\n  cachingStrategy = " + cachingStrategy
            + "\n  pinning=" + pinning
            );
      }

      replicaHandler = initializeReplicaHandler(storageType, stage, newGs, minBytesRcvd, maxBytesRcvd);
      ReplicaInPipelineInterface replica = replicaHandler.getReplica();
      this.replicaInfo = replica;

      this.dropCacheBehindWrites = (cachingStrategy.getDropBehind() == null) ?
        datanode.getDnConf().dropCacheBehindWrites :
          cachingStrategy.getDropBehind();
      this.syncBehindWrites = datanode.getDnConf().syncBehindWrites;
      this.syncBehindWritesInBackground = datanode.getDnConf().
          syncBehindWritesInBackground;

      final boolean isCreate = isDatanode || isTransfer 
          || stage == BlockConstructionStage.PIPELINE_SETUP_CREATE;
      streams = replica.createStreams(isCreate, requestedChecksum);
      assert streams != null : "null streams!";

      this.clientChecksum = requestedChecksum;
      this.diskChecksum = streams.getChecksum();
      this.needsChecksumTranslation = !clientChecksum.equals(diskChecksum);
      this.bytesPerChecksum = diskChecksum.getBytesPerChecksum();
      this.checksumSize = diskChecksum.getChecksumSize();

      this.out = streams.getDataOut();
      if (out instanceof FileOutputStream) {
        this.outFd = ((FileOutputStream)out).getFD();
      } else {
        LOG.warn("Could not get file descriptor for outputstream of class " +
            out.getClass());
      }
      this.checksumOut = new DataOutputStream(new BufferedOutputStream(
          streams.getChecksumOut(), HdfsConstants.SMALL_BUFFER_SIZE));
      if (isCreate) {
        BlockMetadataHeader.writeHeader(checksumOut, diskChecksum);
      }
    } catch (ReplicaAlreadyExistsException bae) {
      throw bae;
    } catch (ReplicaNotFoundException bne) {
      throw bne;
    } catch(IOException ioe) {
      IOUtils.closeStream(this);
      cleanupBlock();

      IOException cause = DatanodeUtil.getCauseIfDiskError(ioe);
      DataNode.LOG.warn("IOException in BlockReceiver constructor. Cause is ",
          cause);

      if (cause != null) {
        ioe = cause;
        datanode.checkDiskErrorAsync();
      }

      throw ioe;
    }
  }

  private ReplicaHandler initializeReplicaHandler(final StorageType storageType, final BlockConstructionStage stage, final long newGs, final long minBytesRcvd, final long maxBytesRcvd) throws IOException {
    if (isDatanode) {
      return datanode.data.createTemporary(storageType, block);
    }

    switch (stage) {
    case PIPELINE_SETUP_CREATE:
      ReplicaHandler handler1 = datanode.data.createRbw(storageType, block, allowLazyPersist);
      datanode.notifyNamenodeReceivingBlock(block, handler1.getReplica().getStorageUuid());
      return handler1;
    case PIPELINE_SETUP_STREAMING_RECOVERY:
      ReplicaHandler handler2 = datanode.data.recoverRbw(block, newGs, minBytesRcvd, maxBytesRcvd);
      block.setGenerationStamp(newGs);
      return handler2;
    case PIPELINE_SETUP_APPEND:
      ReplicaHandler handler3 = datanode.data.append(block, newGs, minBytesRcvd);
      block.setGenerationStamp(newGs);
      datanode.notifyNamenodeReceivingBlock(block, handler3.getReplica().getStorageUuid());
      return handler3;
    case PIPELINE_SETUP_APPEND_RECOVERY:
      ReplicaHandler handler4 = datanode.data.recoverAppend(block, newGs, minBytesRcvd);
      block.setGenerationStamp(newGs);
      datanode.notifyNamenodeReceivingBlock(block, handler4.getReplica().getStorageUuid());
      return handler4;
    case TRANSFER_RBW:
    case TRANSFER_FINALIZED:
      return datanode.data.createTemporary(storageType, block);
    default:
      throw new IOException("Unsupported stage " + stage + " while receiving block " + block + " from " + inAddr);
    }
  }
