private boolean chooseProxySource() {
  final DatanodeInfo targetDN = target.getDatanodeInfo();
  if (isSourceEqualsTargetAndAddable(targetDN)) {
    return true;
  }

  StorageGroup proxy = findProxyInNodeGroup(targetDN);
  if (proxy != null) {
    return true;
  }

  proxy = findProxyOnSameRack(targetDN);
  if (proxy != null) {
    return true;
  }

  proxy = findAnyProxy(targetDN);
  return proxy != null;
}

private boolean isSourceEqualsTargetAndAddable(DatanodeInfo targetDN) {
  return source.getDatanodeInfo().equals(targetDN) && addTo(source);
}

private StorageGroup findProxyInNodeGroup(DatanodeInfo targetDN) {
  if (!cluster.isNodeGroupAware()) {
    return null;
  }
  for (StorageGroup loc : block.getLocations()) {
    if (cluster.isOnSameNodeGroup(loc.getDatanodeInfo(), targetDN) && addTo(loc)) {
      return loc;
    }
  }
  return null;
}

private StorageGroup findProxyOnSameRack(DatanodeInfo targetDN) {
  for (StorageGroup loc : block.getLocations()) {
    if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN) && addTo(loc)) {
      return loc;
    }
  }
  return null;
}

private StorageGroup findAnyProxy(DatanodeInfo targetDN) {
  for (StorageGroup loc : block.getLocations()) {
    if (addTo(loc)) {
      return loc;
    }
  }
  return null;
}

