private boolean chooseProxySource() {
  final DatanodeInfo targetDN = target.getDatanodeInfo();
  // if source and target are same nodes then no need of proxy
  if (source.getDatanodeInfo().equals(targetDN) && addTo(source)) {
    return true;
  }

  // Use lookup table to avoid nested switch/branch depth
  final ProxySelectionResult result = chooseProxyViaTopology(targetDN);
  return result != null && addTo(result.getStorageGroup());
}

/**
 * Try to select a proxy based on cluster topology:
 * 1. Same nodegroup if supported
 * 2. Same rack
 * 3. Any non-busy replica
 * Returns null if none selected.
 */
private ProxySelectionResult chooseProxyViaTopology(final DatanodeInfo targetDN) {
  List<StorageGroup> locations = block.getLocations();
  if (cluster.isNodeGroupAware()) {
    for (StorageGroup loc : locations) {
      if (cluster.isOnSameNodeGroup(loc.getDatanodeInfo(), targetDN)) {
        return new ProxySelectionResult(loc, ProxySelectionReason.NODEGROUP);
      }
    }
  }

  for (StorageGroup loc : locations) {
    if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN)) {
      return new ProxySelectionResult(loc, ProxySelectionReason.RACK);
    }
  }

  for (StorageGroup loc : locations) {
    return new ProxySelectionResult(loc, ProxySelectionReason.ANY);
  }

  return null;
}

/** Result of proxy selection process */
private static class ProxySelectionResult {
  private final StorageGroup storageGroup;
  private final ProxySelectionReason reason;

  ProxySelectionResult(StorageGroup storageGroup, ProxySelectionReason reason) {
    this.storageGroup = storageGroup;
    this.reason = reason;
  }

  public StorageGroup getStorageGroup() {
    return storageGroup;
  }

  public ProxySelectionReason getReason() {
    return reason;
  }
}

private enum ProxySelectionReason {
  NODEGROUP, RACK, ANY
