public RemoteIterator<LocatedFileStatus> listFiles(
    final Path f, final boolean recursive) throws AccessControlException,
    FileNotFoundException, UnsupportedFileSystemException, 
    IOException {
  return new RemoteIterator<LocatedFileStatus>() {
    private Stack<RemoteIterator<LocatedFileStatus>> itors = 
      new Stack<RemoteIterator<LocatedFileStatus>>();
    RemoteIterator<LocatedFileStatus> curItor = listLocatedStatus(f);
    LocatedFileStatus curFile;

    @Override
    public boolean hasNext() throws IOException {
      while (curFile == null) {
        if (curItor.hasNext()) {
          handleFileStat(curItor.next());
        } else if (!itors.empty()) {
          curItor = itors.pop();
        } else {
          return false;
        }
      }
      return true;
    }

    private void handleFileStat(LocatedFileStatus stat)
    throws IOException {
      if (stat.isFile()) { 
        curFile = stat;
      } else if (stat.isSymlink()) { 
        resolveAndProcessSymlink(stat);
      } else if (recursive) { 
        pushDirectoryIterator(stat);
      }
    }

    private void resolveAndProcessSymlink(LocatedFileStatus stat)
        throws IOException {
      FileStatus symstat = FileContext.this.getFileStatus(stat.getSymlink());
      if (symstat.isFile() || (recursive && symstat.isDirectory())) {
        itors.push(curItor);
        curItor = listLocatedStatus(stat.getPath());
      }
    }

    private void pushDirectoryIterator(LocatedFileStatus stat)
        throws IOException {
      itors.push(curItor);
      curItor = listLocatedStatus(stat.getPath());
    }

    @Override
    public LocatedFileStatus next() throws IOException {
      if (hasNext()) {
        LocatedFileStatus result = curFile;
        curFile = null;
        return result;
      } 
      throw new java.util.NoSuchElementException("No more entry in " + f);
    }
  };
