public void processKeyEvent(KeyEvent evt)
{
	if(isClosed())
		return;

	if (handleInComponent(evt))
		return;

	if (handleInTextComponent(evt))
		return;

	if (evt.isConsumed())
		return;

	evt = KeyEventWorkaround.processKeyEvent(evt);
	if (evt == null)
		return;

	handleKeyEvent(evt);
	if (!evt.isConsumed())
		super.processKeyEvent(evt);
}

/**
 * Checks if the event should be handled by the focused component's InputMap/ActionMap.
 */
private boolean handleInComponent(KeyEvent evt)
{
	if(!(getFocusOwner() instanceof JComponent))
		return false;

	JComponent comp = (JComponent)getFocusOwner();
	InputMap map = comp.getInputMap();
	ActionMap am = comp.getActionMap();

	if(map != null && am != null && comp.isEnabled())
	{
		Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
		if(binding != null && am.get(binding) != null)
			return true;
	}
	return false;
}

/**
 * Checks if the event should be skipped in JTextComponent context to avoid double handling.
 */
private boolean handleInTextComponent(KeyEvent evt)
{
	if(!(getFocusOwner() instanceof JTextComponent))
		return false;

	if(evt.getID() == KeyEvent.KEY_PRESSED)
	{
		switch(evt.getKeyCode())
		{
		case KeyEvent.VK_BACK_SPACE:
		case KeyEvent.VK_TAB:
		case KeyEvent.VK_ENTER:
			return true;
		}
	}

	Keymap keymap = ((JTextComponent)getFocusOwner()).getKeymap();
	return keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null;
}

