    /**
     * Refactored zoom method with reduced cognitive complexity using a parameter
     * object to encapsulate zoom selection details.
     */
    public void zoom(Rectangle2D selection) {
        ParamChecks.nullNotPermitted(selection, "selection");

        ZoomParameters params = new ZoomParameters.Builder()
                .selection(selection)
                .info(this.info)
                .translateScreenToJava2D(this::translateScreenToJava2D)
                .scale(this::scale)
                .orientation(this.orientation)
                .build();

        DrawAreaData data = params.getDrawAreaData();
        if (!data.isValid()) {
            return;
        }

        ZoomAxisData axisData = params.calculateAxisData(data);
        if (!axisData.isValid()) {
            return;
        }

        applyZoom(params.getChartPlot(), axisData, params.getPlotInfo(), params.getSelectOrigin());
    }

    /**
     * Internal parameter object encapsulating zoom operation inputs.
     */
    private static class ZoomParameters {
        private final Rectangle2D selection;
        private final ChartRenderingInfo info;
        private final Function<Point2D, Point> screenTranslator;
        private final Function<Rectangle2D, Rectangle2D> scaler;
        private final PlotOrientation orientation;
        private Plot chartPlot;
        private PlotRenderingInfo plotInfo;

        private ZoomParameters(Builder builder) {
            this.selection = builder.selection;
            this.info = builder.info;
            this.screenTranslator = builder.screenTranslator;
            this.scaler = builder.scaler;
            this.orientation = builder.orientation;
        }

        public static class Builder {
            private Rectangle2D selection;
            private ChartRenderingInfo info;
            private Function<Point2D, Point> screenTranslator;
            private Function<Rectangle2D, Rectangle2D> scaler;
            private PlotOrientation orientation;

            public Builder selection(Rectangle2D selection) {
                this.selection = selection;
                return this;
            }

            public Builder info(ChartRenderingInfo info) {
                this.info = info;
                return this;
            }

            public Builder translateScreenToJava2D(Function<Point2D, Point> translator) {
                this.screenTranslator = translator;
                return this;
            }

            public Builder scale(Function<Rectangle2D, Rectangle2D> scaler) {
                this.scaler = scaler;
                return this;
            }

            public Builder orientation(PlotOrientation orientation) {
                this.orientation = orientation;
                return this;
            }

            public ZoomParameters build() {
                return new ZoomParameters(this);
            }
        }

        public DrawAreaData getDrawAreaData() {
            Point2D selectOrigin = screenTranslator.apply(new Point(
                    (int) Math.ceil(selection.getX()),
                    (int) Math.ceil(selection.getY())));
            Rectangle2D scaledDataArea = scaler.apply(info.getPlotInfo().getDataArea());
            this.chartPlot = info.getChart().getPlot();
            this.plotInfo = info.getPlotInfo();

            return new DrawAreaData(scaledDataArea, selectOrigin, chartPlot instanceof Zoomable);
        }

        public PlotRenderingInfo getPlotInfo() {
            return plotInfo;
        }

        public Point2D getSelectOrigin() {
            return ((DrawAreaData) getDrawAreaData()).selectOrigin;
        }

        public Plot getChartPlot() {
            return chartPlot;
        }

        public ZoomAxisData calculateAxisData(DrawAreaData data) {
            if (!data.isValid() || selection.getHeight() <= 0 || selection.getWidth() <= 0) {
                return ZoomAxisData.invalid();
            }

            double hLower = (selection.getMinX() - data.scaledDataArea.getMinX())
                    / data.scaledDataArea.getWidth();
            double hUpper = (selection.getMaxX() - data.scaledDataArea.getMinX())
                    / data.scaledDataArea.getWidth();
            double vLower = (data.scaledDataArea.getMaxY() - selection.getMaxY())
                    / data.scaledDataArea.getHeight();
            double vUpper = (data.scaledDataArea.getMaxY() - selection.getMinY())
                    / data.scaledDataArea.getHeight();

            return new ZoomAxisData(hLower, hUpper, vLower, vUpper, orientation);
        }

        private static class DrawAreaData {
            private final Rectangle2D scaledDataArea;
            private final Point2D selectOrigin;
            private final boolean isZoomable;

            public DrawAreaData(Rectangle2D scaledDataArea, Point2D selectOrigin, boolean isZoomable) {
                this.scaledDataArea = scaledDataArea;
                this.selectOrigin = selectOrigin;
                this.isZoomable = isZoomable;
            }

            public boolean isValid() {
                return isZoomable && scaledDataArea != null;
            }
        }

        private static class ZoomAxisData {
            private final double hLower;
            private final double hUpper;
            private final double vLower;
            private final double vUpper;
            private final PlotOrientation orientation;
            private final boolean valid;

            public ZoomAxisData(double hLower, double hUpper, double vLower, double vUpper,
                                PlotOrientation orientation) {
                this.hLower = hLower;
                this.hUpper = hUpper;
                this.vLower = vLower;
                this.vUpper = vUpper;
                this.orientation = orientation;
                this.valid = true;
            }

            public static ZoomAxisData invalid() {
                return new ZoomAxisData(0, 0, 0, 0, PlotOrientation.VERTICAL, false);
            }

            public boolean isValid() {
                return valid;
            }
        }
    }

    /**
     * Applies zoom to axes based on computed axis data.
     *
     * @param plot the plot to zoom
     * @param axisData the computed axis zoom parameters
     * @param plotInfo the plot rendering info
     * @param selectOrigin the selection origin point
     */
    private void applyZoom(Plot plot, ZoomAxisData axisData, PlotRenderingInfo plotInfo,
                           Point2D selectOrigin) {
        if (plot instanceof Zoomable) {
            boolean savedNotify = plot.isNotify();
            plot.setNotify(false);
            Zoomable z = (Zoomable) plot;
            if (axisData.orientation == PlotOrientation.HORIZONTAL) {
                z.zoomDomainAxes(axisData.vLower, axisData.vUpper, plotInfo, selectOrigin);
                z.zoomRangeAxes(axisData.hLower, axisData.hUpper, plotInfo, selectOrigin);
            } else {
                z.zoomDomainAxes(axisData.hLower, axisData.hUpper, plotInfo, selectOrigin);
                z.zoomRangeAxes(axisData.vLower, axisData.vUpper, plotInfo, selectOrigin);
            }
            plot.setNotify(savedNotify);
        }
    }
