        if (this.toolTipGenerator != null) {
            clone.toolTipGenerator = (PieToolTipGenerator) 
                    ObjectUtilities.clone(this.toolTipGenerator);
        }
        if (this.urlGenerator != null) {
            if (this.urlGenerator instanceof PublicCloneable) {
                clone.urlGenerator = (PieURLGenerator) ObjectUtilities.clone(
                        this.urlGenerator);
            } else {
                clone.urlGenerator = this.urlGenerator;
            }
        }
        clone.legendLabelGenerator = this.legendLabelGenerator;
        clone.legendLabelToolTipGenerator = this.legendLabelToolTipGenerator;
